data: {"id":"gen-1792311109-XdFSjbtHyOZuKQOUMua8","object":"chat.completion.chunk","created":1792311109,"model":"deepseek/deepseek-v4.1-flash","provider":"DigitalOcean","choices":[{"index":0,"delta":{"content":null,"role":"assistant","tool_calls":[{"index":0,"function":{"arguments":"{\"path\":\"textkit/diffs.py\",\"content\":\"\\\"\\\"\\\"Compare sequences of lines and render the difference.\\n\\nPublic API\\n----------\\n``unified_diff(a, b, from_label='a', to_label='b', context=3)``\\n    Return a unified diff between the line lists ``a`` and ``b`` as a string.\\n\\n``similarity(a, b)``\\n    Return the fraction of lines the two sequences share, between 0.0 and 1.0.\\n\\n``changed_lines(a, b)``\\n    Return ``(added, removed)`` line counts between ``a`` and ``b``.\\n\\n``common_prefix(a, b)``\\n    Return the number of leading lines ``a`` and ``b`` have in common.\\n\\n``common_suffix(a, b)``\\n    Return the number of trailing lines ``a`` and ``b`` have in common.\\n\\n``apply_patch(lines, patch)``\\n    Apply a hunk list produced by :func:`hunks` to ``lines``.\\n\\n``hunks(a, b, context=3)``\\n    Return the change hunks between ``a`` and ``b`` as plain data.\\n\\nOnly the standard library is used.\\n\\\"\\\"\\\"\\n\\nimport difflib\\n\\n__all__ = [\\n    \\\"unified_diff\\\",\\n    \\\"similarity\\\",\\n    \\\"changed_lines\\\",\\n    \\\"common_prefix\\\",\\n    \\\"common_suffix\\\",\\n    \\\"hunks\\\",\\n    \\\"apply_patch\\\",\\n    \\\"DEFAULT_CONTEXT\\\",\\n]\\n\\nDEFAULT_CONTEXT = 3\\n\\n\\ndef _check_lines(lines, name):\\n    if isinstance(lines, str):\\n        lines = lines.splitlines()\\n    try:\\n        items = list(lines)\\n    except TypeError:\\n        raise TypeError(\\\"%s must be a sequence of lines\\\" % name)\\n    for item in items:\\n        if not isinstance(item, str):\\n            raise TypeError(\\\"%s must contain only str lines\\\" % name)\\n    return items\\n\\n\\ndef unified_diff(a, b, from_label=\\\"a\\\", to_label=\\\"b\\\", context=DEFAULT_CONTEXT):\\n    \\\"\\\"\\\"Return a unified diff between the lines of ``a`` and ``b``.\\\"\\\"\\\"\\n    left = _check_lines(a, \\\"a\\\")\\n    right = _check_lines(b, \\\"b\\\")\\n    if not isinstance(context, int) or isinstance(context, bool):\\n        raise TypeError(\\\"context must be an int\\\")\\n    if context < 0:\\n        raise ValueError(\\\"context must be non-negative\\\")\\n    return \\\"\\\".join(\\n        difflib.unified_diff(\\n            left,\\n            right,\\n            fromfile=from_label,\\n            tofile=to_label,\\n            lineterm=\\\"\\\\n\\\",\\n            n=context,\\n        )\\n    )\\n\\n\\ndef hunks(a, b, context=DEFAULT_CONTEXT):\\n    \\\"\\\"\\\"Return the change hunks between ``a`` and ``b`` as plain data.\\\"\\\"\\\"\\n    left = _check_lines(a, \\\"a\\\")\\n    right = _check_lines(b, \\\"b\\\")\\n    matcher = difflib.SequenceMatcher(a=left, b=right, autojunk=False)\\n    result = []\\n    for group in matcher.get_grouped_opcodes(context):\\n        for tag, i1, i2, j1, j2 in group:\\n            result.append(\\n                {\\n                    \\\"tag\\\": tag,\\n                    \\\"a_start\\\": i1,\\n                    \\\"a_end\\\": i2,\\n                    \\\"b_start\\\": j1,\\n                    \\\"b_end\\\": j2,\\n                }\\n            )\\n    return result\\n\\n\\ndef apply_patch(lines, patch):\\n    \\\"\\\"\\\"Apply ``patch`` (from :func:`hunks`) to ``lines`` and return the result.\\\"\\\"\\\"\\n    left = _check_lines(lines, \\\"lines\\\")\\n    operations = []\\n    for hunk in patch:\\n        if not isinstance(hunk, dict):\\n            raise TypeError(\\\"each hunk must be a dict\\\")\\n        tag = hunk[\\\"tag\\\"]\\n        if tag not in (\\\"equal\\\", \\\"replace\\\", \\\"delete\\\", \\\"insert\\\"):\\n            raise ValueError(\\\"unknown hunk tag %r\\\" % (tag,))\\n        operations.append(\\n            (\\n                hunk[\\\"a_start\\\"],\\n                hunk[\\\"a_end\\\"],\\n                tag,\\n                left[hunk[\\\"b_start\\\"]:hunk[\\\"b_end\\\"]],\\n            )\\n        )\\n    result = []\\n    cursor = 0\\n    for a_start, a_end, tag, replacement in operations:\\n        if a_start < cursor:\\n            raise ValueError(\\\"overlapping hunks\\\")\\n        result.extend(left[cursor:a_start])\\n        if tag in (\\\"replace\\\", \\\"insert\\\"):\\n            result.extend(replacement)\\n        cursor = a_end\\n    result.extend(left[cursor:])\\n    return result\\n\\n\\ndef _match_count(a, b):\\n    matcher = difflib.SequenceMatcher(a=a, b=b, autojunk=False)\\n    return sum(size for _, _, size in matcher.get_matching_blocks())\\n\\n\\ndef similarity(a, b):\\n    \\\"\\\"\\\"Return the fraction of shared lines between ``a`` and ``b``.\\\"\\\"\\\"\\n    left = _check_lines(a, \\\"a\\\")\\n    right = _check_lines(b, \\\"b\\\")\\n    if not left and not right:\\n        return 1.0\\n    matched = _match_count(left, right)\\n    return matched / max(len(left), len(right))\\n\\n\\ndef changed_lines(a, b):\\n    \\\"\\\"\\\"Return ``(added, removed)`` line counts between ``a`` and ``b``.\\\"\\\"\\\"\\n    left = _check_lines(a, \\\"a\\\")\\n    right = _check_lines(b, \\\"b\\\")\\n    removed = len(left) - _match_count(left, right)\\n    added = len(right) - _match_count(left, right)\\n    return added, removed\\n\\n\\ndef common_prefix(a, b):\\n    \\\"\\\"\\\"Return the number of leading lines ``a`` and ``b`` share.\\\"\\\"\\\"\\n    left = _check_lines(a, \\\"a\\\")\\n    right = _check_lines(b, \\\"b\\\")\\n    count = 0\\n    for first, second in zip(left, right):\\n        if first != second:\\n            break\\n        count += 1\\n    return count\\n\\n\\ndef common_suffix(a, b):\\n    \\\"\\\"\\\"Return the number of trailing lines ``a`` and ``b`` share.\\\"\\\"\\\"\\n    left = _check_lines(a, \\\"a\\\")\\n    right = _check_lines(b, \\\"b\\\")\\n    count = 0\\n    for first, second in zip(reversed(left), reversed(right)):\\n        if first != second:\\n            break\\n        count += 1\\n    return count\\n\"}"}}]},"finish_reason":null,"native_finish_reason":null}]}

