data: {"id":"gen-1792311117-JWMUOeRWntd3RfSQybp2","object":"chat.completion.chunk","created":1792311117,"model":"deepseek/deepseek-v4.1-flash","provider":"DigitalOcean","choices":[{"index":0,"delta":{"content":null,"role":"assistant","tool_calls":[{"index":0,"function":{"arguments":"{\"content\":\"import unittest\\n\\nfrom textkit.diffs import (\\n    DEFAULT_CONTEXT,\\n    apply_patch,\\n    changed_lines,\\n    common_prefix,\\n    common_suffix,\\n    hunks,\\n    similarity,\\n    unified_diff,\\n)\\n\\n\\nclass DiffsTests(unittest.TestCase):\\n    def test_unified_diff_basic(self):\\n        a = [\\\"one\\\", \\\"two\\\", \\\"three\\\"]\\n        b = [\\\"one\\\", \\\"TWO\\\", \\\"three\\\"]\\n        diff = unified_diff(a, b, from_label=\\\"old\\\", to_label=\\\"new\\\")\\n        self.assertIn(\\\"--- old\\\", diff)\\n        self.assertIn(\\\"+++ new\\\", diff)\\n        self.assertIn(\\\"-two\\\", diff)\\n        self.assertIn(\\\"+TWO\\\", diff)\\n        self.assertTrue(diff.endswith(\\\"\\\\n\\\"))\\n        self.assertEqual(DEFAULT_CONTEXT, 3)\\n\\n    def test_unified_diff_accepts_strings_and_context(self):\\n        diff = unified_diff(\\\"a\\\\nb\\\\nc\\\\n\\\", \\\"a\\\\nc\\\\n\\\", context=0)\\n        self.assertIn(\\\"-b\\\", diff)\\n        self.assertNotIn(\\\" a\\\", diff)\\n        with self.assertRaises(ValueError):\\n            unified_diff([\\\"a\\\"], [\\\"b\\\"], context=-1)\\n        with self.assertRaises(TypeError):\\n            unified_diff([\\\"a\\\"], [\\\"b\\\"], context=\\\"1\\\")\\n\\n    def test_common_prefix_and_suffix(self):\\n        a = [\\\"a\\\", \\\"b\\\", \\\"c\\\", \\\"d\\\"]\\n        b = [\\\"a\\\", \\\"b\\\", \\\"x\\\", \\\"d\\\"]\\n        self.assertEqual(common_prefix(a, b), 2)\\n        self.assertEqual(common_suffix(a, b), 1)\\n        self.assertEqual(common_prefix([], []), 0)\\n        self.assertEqual(common_suffix([\\\"a\\\"], [\\\"b\\\"]), 0)\\n\\n    def test_similarity_and_changed_lines(self):\\n        a = [\\\"a\\\", \\\"b\\\", \\\"c\\\"]\\n        self.assertEqual(similarity(a, a), 1.0)\\n        self.assertEqual(similarity([], []), 1.0)\\n        self.assertEqual(similarity(a, []), 0.0)\\n        self.assertEqual(changed_lines(a, a), (0, 0))\\n        added, removed = changed_lines([\\\"a\\\", \\\"b\\\", \\\"c\\\"], [\\\"a\\\", \\\"c\\\", \\\"d\\\"])\\n        self.assertEqual(added, 1)\\n        self.assertEqual(removed, 1)\\n\\n    def test_hunks_and_apply_patch(self):\\n        a = [\\\"a\\\", \\\"b\\\", \\\"c\\\", \\\"d\\\", \\\"e\\\"]\\n        b = [\\\"a\\\", \\\"B\\\", \\\"c\\\", \\\"d\\\", \\\"E\\\"]\\n        patch = hunks(a, b, context=0)\\n        self.assertTrue(patch)\\n        self.assertEqual(apply_patch(a, patch), b)\\n        self.assertEqual(apply_patch(a, hunks(a, a)), a)\\n        with self.assertRaises(ValueError):\\n            apply_patch(a, [{\\\"tag\\\": \\\"nope\\\", \\\"a_start\\\": 0, \\\"a_end\\\": 0,\\n                             \\\"b_start\\\": 0, \\\"b_end\\\": 0}])\\n        with self.assertRaises(TypeError):\\n            apply_patch(a, [\\\"not a dict\\\"])\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main()\\n\",\"path\":\"tests/test_diffs.py\"}"}}]},"finish_reason":null,"native_finish_reason":null}]}

